package com.deathmessagetracker;

final class DeathMessage
{
    private final String monster;
    private final String username;
    private final int level;
    private final int damage;
    private final String location;

    DeathMessage(String monster, String username, int level, int damage, String location)
    {
        this.monster = monster;
        this.username = username;
        this.level = level;
        this.damage = damage;
        this.location = location;
    }

    String getMonster()
    {
        return monster;
    }

    String getUsername()
    {
        return username;
    }

    int getLevel()
    {
        return level;
    }

    int getDamage()
    {
        return damage;
    }

    String getLocation()
    {
        return location;
    }
}

package com.deathmessagetracker;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

final class DeathMessageParser
{
    private static final Pattern LEGACY_FORMATTING_TAG = Pattern.compile("@[A-Za-z0-9_]+@");
    private static final Pattern DEATH_MESSAGE = Pattern.compile(
        "^(.+?)\\s+killed\\s+(.+?)\\s*\\((\\d{1,4})\\)\\s+with\\s+an?\\s+(\\d+)\\s+damage\\s+hit\\s+in\\s+(.+?)[.!]?$",
        Pattern.CASE_INSENSITIVE);

    private DeathMessageParser()
    {
    }

    static Optional<DeathMessage> parse(String chatMessage)
    {
        if (chatMessage == null)
        {
            return Optional.empty();
        }

        String plainText = LEGACY_FORMATTING_TAG.matcher(
                Text.removeFormattingTags(Text.removeTags(chatMessage)))
            .replaceAll("")
            .replace('\u00A0', ' ')
            .trim()
            .replaceAll("\\s+", " ");
        Matcher matcher = DEATH_MESSAGE.matcher(plainText);
        if (!matcher.matches())
        {
            return Optional.empty();
        }

        try
        {
            return Optional.of(new DeathMessage(
                matcher.group(1).trim(),
                matcher.group(2).trim(),
                Integer.parseInt(matcher.group(3)),
                Integer.parseInt(matcher.group(4)),
                matcher.group(5).trim()));
        }
        catch (NumberFormatException ignored)
        {
            return Optional.empty();
        }
    }
}

package com.deathmessagetracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.JTable;
import javax.swing.SwingConstants;
import javax.swing.table.DefaultTableModel;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.ColorScheme;

final class DeathMessageTrackerPanel extends PluginPanel
{
    private final JLabel total = valueLabel();
    private final JLabel levelAverage = valueLabel();
    private final JLabel levelRange = valueLabel();
    private final JLabel damageAverage = valueLabel();
    private final JLabel damageRange = valueLabel();
    private final DefaultTableModel monsters = tableModel("Monster", "Count");
    private final DefaultTableModel players = tableModel("Repeated player", "Count");
    private final DefaultTableModel levels = tableModel("Level", "Count");
    private final DefaultTableModel locations = tableModel("Location", "Count");
    private final DefaultTableModel damages = tableModel("Damage", "Count");

    DeathMessageTrackerPanel(Runnable exportAction, Runnable clearAction)
    {
        super(false);
        setLayout(new BorderLayout(0, 8));
        setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        JPanel summary = new JPanel(new GridLayout(5, 2, 6, 3));
        summary.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        summary.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR),
            BorderFactory.createEmptyBorder(7, 7, 7, 7)));
        addSummaryRow(summary, "Messages", total);
        addSummaryRow(summary, "Level avg / median", levelAverage);
        addSummaryRow(summary, "Level range", levelRange);
        addSummaryRow(summary, "Damage avg / median", damageAverage);
        addSummaryRow(summary, "Damage range", damageRange);

        JTabbedPane tabs = new JTabbedPane();
        tabs.addTab("Monsters", table(monsters));
        tabs.addTab("Players", table(players));
        tabs.addTab("Levels", table(levels));
        tabs.addTab("Places", table(locations));
        tabs.addTab("Damage", table(damages));

        JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
        JButton export = new JButton("Export CSV");
        export.addActionListener(event -> exportAction.run());
        JButton clear = new JButton("Clear");
        clear.addActionListener(event ->
        {
            int choice = JOptionPane.showConfirmDialog(this,
                "Clear all accumulated death-message statistics?",
                "Clear statistics", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
            if (choice == JOptionPane.YES_OPTION)
            {
                clearAction.run();
            }
        });
        buttons.add(export);
        buttons.add(clear);

        JPanel header = new JPanel(new BorderLayout(0, 8));
        header.add(summary, BorderLayout.CENTER);
        header.add(buttons, BorderLayout.SOUTH);
        add(header, BorderLayout.NORTH);
        add(tabs, BorderLayout.CENTER);
    }

    void update(TrackerState.Snapshot snapshot)
    {
        total.setText(Integer.toString(snapshot.getTotalMessages()));
        levelAverage.setText(formatAverages(snapshot.getAverageLevel(), snapshot.getMedianLevel(), snapshot.getTotalMessages()));
        levelRange.setText(formatRange(snapshot.getMinimumLevel(), snapshot.getMaximumLevel()));
        damageAverage.setText(formatAverages(snapshot.getAverageDamage(), snapshot.getMedianDamage(), snapshot.getTotalMessages()));
        damageRange.setText(formatRange(snapshot.getMinimumDamage(), snapshot.getMaximumDamage()));

        fillNamed(monsters, snapshot.getMonsters());
        fillNamed(players, snapshot.getRepeatedPlayers());
        fillNumbers(levels, snapshot.getLevels());
        fillNamed(locations, snapshot.getLocations());
        fillNumbers(damages, snapshot.getDamages());
    }

    private static void addSummaryRow(JPanel panel, String label, JLabel value)
    {
        JLabel name = new JLabel(label);
        name.setForeground(Color.LIGHT_GRAY);
        panel.add(name);
        panel.add(value);
    }

    private static JLabel valueLabel()
    {
        JLabel label = new JLabel("—", SwingConstants.RIGHT);
        label.setForeground(Color.WHITE);
        return label;
    }

    private static JScrollPane table(DefaultTableModel model)
    {
        JTable table = new JTable(model);
        table.setFillsViewportHeight(true);
        table.setAutoCreateRowSorter(true);
        table.getColumnModel().getColumn(1).setMaxWidth(60);
        return new JScrollPane(table);
    }

    private static DefaultTableModel tableModel(String firstColumn, String secondColumn)
    {
        return new DefaultTableModel(new Object[]{firstColumn, secondColumn}, 0)
        {
            @Override
            public boolean isCellEditable(int row, int column)
            {
                return false;
            }

            @Override
            public Class<?> getColumnClass(int columnIndex)
            {
                return columnIndex == 1 ? Integer.class : String.class;
            }
        };
    }

    private static void fillNamed(DefaultTableModel model, List<NamedCount> values)
    {
        model.setRowCount(0);
        for (NamedCount value : values)
        {
            model.addRow(new Object[]{value.getName(), value.getCount()});
        }
    }

    private static void fillNumbers(DefaultTableModel model, List<TrackerState.NumberCount> values)
    {
        model.setRowCount(0);
        for (TrackerState.NumberCount value : values)
        {
            model.addRow(new Object[]{Integer.toString(value.getValue()), value.getCount()});
        }
    }

    private static String formatAverages(double average, double median, int count)
    {
        return count == 0 ? "—" : String.format(Locale.ROOT, "%.1f / %.1f", average, median);
    }

    private static String formatRange(Integer minimum, Integer maximum)
    {
        return minimum == null ? "—" : minimum + "–" + maximum;
    }
}

package com.deathmessagetracker;

import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.Writer;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
    name = "Death Message Tracker",
    description = "Tracks aggregate statistics from monster death messages",
    tags = {"chat", "death", "monster", "statistics", "tracker"},
    internalName = "death-message-tracker",
    legacyDataDirectory = "death-message-tracker"
)
public class DeathMessageTrackerPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(DeathMessageTrackerPlugin.class);
    private static final DateTimeFormatter EXPORT_TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss");
    private static final long SAVE_DELAY_MILLISECONDS = 250;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    private final Object saveLock = new Object();
    private TrackerStore store;
    private volatile TrackerState state;
    private DeathMessageTrackerPanel panel;
    private NavigationButton navigationButton;
    private ScheduledFuture<?> pendingSave;
    private volatile int resetGeneration;
    private volatile boolean loadComplete;

    @Override
    protected void startUp() throws IOException
    {
        Filepath pluginDirectory = getPluginDirectory();
        store = new TrackerStore(gson, pluginDirectory.joinSegment("statistics.json"));
        state = new TrackerState();
        loadComplete = false;
        int loadGeneration = resetGeneration;
        TrackerState loadTarget = state;

        panel = new DeathMessageTrackerPanel(this::exportCsv, this::clearStatistics);
        panel.update(state.snapshot());
        navigationButton = NavigationButton.builder()
            .tooltip("Death Message Tracker")
            .priority(6)
            .icon(createIcon())
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);
        executor.execute(() -> loadState(loadTarget, loadGeneration));
    }

    @Override
    protected void shutDown()
    {
        TrackerState finalState = state;
        cancelPendingSave();
        if (loadComplete)
        {
            executor.execute(() -> persist(finalState));
        }
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
        }
        navigationButton = null;
        panel = null;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        DeathMessageParser.parse(event.getMessage()).ifPresent(message ->
        {
            TrackerState currentState = state;
            currentState.add(message);
            scheduleSave(currentState);
            TrackerState.Snapshot snapshot = currentState.snapshot();
            SwingUtilities.invokeLater(() ->
            {
                if (panel != null)
                {
                    panel.update(snapshot);
                }
            });
        });
    }

    private void clearStatistics()
    {
        resetGeneration++;
        TrackerState emptyState = new TrackerState();
        state = emptyState;
        scheduleSave(emptyState);
        panel.update(emptyState.snapshot());
    }

    private void loadState(TrackerState loadTarget, int loadGeneration)
    {
        try
        {
            TrackerState loaded = store.load();
            if (state == loadTarget && resetGeneration == loadGeneration)
            {
                loadTarget.mergeFrom(loaded);
            }
        }
        catch (IOException | RuntimeException exception)
        {
            LOG.warn("Unable to load death-message statistics; continuing with empty statistics", exception);
        }
        finally
        {
            loadComplete = true;
            TrackerState currentState = state;
            scheduleSave(currentState);
            updatePanel(currentState.snapshot());
        }
    }

    private synchronized void scheduleSave(TrackerState stateToSave)
    {
        if (!loadComplete)
        {
            return;
        }
        cancelPendingSave();
        pendingSave = executor.schedule(() -> persist(stateToSave), SAVE_DELAY_MILLISECONDS, TimeUnit.MILLISECONDS);
    }

    private synchronized void cancelPendingSave()
    {
        if (pendingSave != null)
        {
            pendingSave.cancel(false);
            pendingSave = null;
        }
    }

    private void persist(TrackerState stateToSave)
    {
        synchronized (saveLock)
        {
            if (stateToSave != state || store == null)
            {
                return;
            }
            try
            {
                store.save(stateToSave);
            }
            catch (IOException exception)
            {
                LOG.warn("Unable to save death-message statistics", exception);
            }
        }
    }

    private void exportCsv()
    {
        TrackerState.Snapshot snapshot = state.snapshot();
        executor.execute(() -> writeCsv(snapshot));
    }

    private void writeCsv(TrackerState.Snapshot snapshot)
    {
        try
        {
            Filepath exportDirectory = getPluginDirectory().joinSegment("exports");
            exportDirectory.createDirectories();
            Filepath exportFile = exportDirectory.joinSegment(
                "death-message-statistics_" + EXPORT_TIME.format(LocalDateTime.now()) + ".csv");
            try (Writer writer = exportFile.openBufferedWriter(
                StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE))
            {
                writer.write("category,value,count\n");
                writeNamed(writer, "monster", snapshot.getMonsters());
                writeNamed(writer, "repeated_player", snapshot.getRepeatedPlayers());
                writeNumbers(writer, "level", snapshot.getLevels());
                writeNamed(writer, "location", snapshot.getLocations());
                writeNumbers(writer, "damage", snapshot.getDamages());
            }
            SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(panel,
                "Exported to:\n" + exportFile, "Export complete", JOptionPane.INFORMATION_MESSAGE));
        }
        catch (IOException exception)
        {
            LOG.warn("Unable to export death-message statistics", exception);
            SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(panel,
                "The CSV export could not be written.", "Export failed", JOptionPane.ERROR_MESSAGE));
        }
    }

    private void updatePanel(TrackerState.Snapshot snapshot)
    {
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.update(snapshot);
            }
        });
    }

    private static void writeNamed(Writer writer, String category, Iterable<NamedCount> values) throws IOException
    {
        for (NamedCount value : values)
        {
            writer.write(category + "," + csv(value.getName()) + "," + value.getCount() + "\n");
        }
    }

    private static void writeNumbers(Writer writer, String category, Iterable<TrackerState.NumberCount> values)
        throws IOException
    {
        for (TrackerState.NumberCount value : values)
        {
            writer.write(category + "," + value.getValue() + "," + value.getCount() + "\n");
        }
    }

    private static String csv(String value)
    {
        return '"' + value.replace("\"", "\"\"") + '"';
    }

    private static BufferedImage createIcon()
    {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(new Color(235, 125, 35));
        graphics.fillOval(1, 1, 14, 12);
        graphics.fillRect(4, 10, 8, 5);
        graphics.setColor(new Color(45, 35, 28));
        graphics.fillOval(4, 5, 3, 3);
        graphics.fillOval(9, 5, 3, 3);
        graphics.fillRect(7, 9, 2, 2);
        graphics.dispose();
        return image;
    }
}

package com.deathmessagetracker;

final class NamedCount
{
    private String name;
    private int count;

    NamedCount()
    {
    }

    NamedCount(String name)
    {
        this.name = name;
        this.count = 1;
    }

    void increment()
    {
        count++;
    }

    void add(int amount)
    {
        count += amount;
    }

    String getName()
    {
        return name;
    }

    int getCount()
    {
        return count;
    }
}

package com.deathmessagetracker;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

final class TrackerState
{
    private int totalMessages;
    private long levelTotal;
    private long damageTotal;
    private Integer minimumLevel;
    private Integer maximumLevel;
    private Integer minimumDamage;
    private Integer maximumDamage;
    private Map<String, NamedCount> monsters = new HashMap<>();
    private Map<String, NamedCount> players = new HashMap<>();
    private Map<String, NamedCount> locations = new HashMap<>();
    private Map<Integer, Integer> levels = new HashMap<>();
    private Map<Integer, Integer> damages = new HashMap<>();

    synchronized void add(DeathMessage message)
    {
        totalMessages++;
        levelTotal += message.getLevel();
        damageTotal += message.getDamage();
        minimumLevel = minimumLevel == null ? message.getLevel() : Math.min(minimumLevel, message.getLevel());
        maximumLevel = maximumLevel == null ? message.getLevel() : Math.max(maximumLevel, message.getLevel());
        minimumDamage = minimumDamage == null ? message.getDamage() : Math.min(minimumDamage, message.getDamage());
        maximumDamage = maximumDamage == null ? message.getDamage() : Math.max(maximumDamage, message.getDamage());

        incrementNamed(monsters, message.getMonster());
        incrementNamed(players, message.getUsername());
        incrementNamed(locations, message.getLocation());
        levels.merge(message.getLevel(), 1, Integer::sum);
        damages.merge(message.getDamage(), 1, Integer::sum);
    }

    synchronized void mergeFrom(TrackerState other)
    {
        if (other == null)
        {
            return;
        }

        other.normalizeAfterLoad();
        synchronized (other)
        {
            totalMessages += other.totalMessages;
            levelTotal += other.levelTotal;
            damageTotal += other.damageTotal;
            minimumLevel = minimum(minimumLevel, other.minimumLevel);
            maximumLevel = maximum(maximumLevel, other.maximumLevel);
            minimumDamage = minimum(minimumDamage, other.minimumDamage);
            maximumDamage = maximum(maximumDamage, other.maximumDamage);
            mergeNamed(monsters, other.monsters);
            mergeNamed(players, other.players);
            mergeNamed(locations, other.locations);
            other.levels.forEach((value, count) -> levels.merge(value, count, Integer::sum));
            other.damages.forEach((value, count) -> damages.merge(value, count, Integer::sum));
        }
    }

    synchronized String toJson(Gson gson)
    {
        return gson.toJson(this);
    }

    synchronized Snapshot snapshot()
    {
        return new Snapshot(
            totalMessages,
            levelTotal,
            damageTotal,
            minimumLevel,
            maximumLevel,
            minimumDamage,
            maximumDamage,
            sortedNamed(monsters, false),
            sortedNamed(players, true),
            sortedNamed(locations, false),
            sortedNumbers(levels),
            sortedNumbers(damages));
    }

    synchronized void normalizeAfterLoad()
    {
        if (monsters == null)
        {
            monsters = new HashMap<>();
        }
        if (players == null)
        {
            players = new HashMap<>();
        }
        if (locations == null)
        {
            locations = new HashMap<>();
        }
        if (levels == null)
        {
            levels = new HashMap<>();
        }
        if (damages == null)
        {
            damages = new HashMap<>();
        }
    }

    private static void incrementNamed(Map<String, NamedCount> counts, String displayName)
    {
        String key = displayName.toLowerCase(Locale.ROOT);
        NamedCount count = counts.get(key);
        if (count == null)
        {
            counts.put(key, new NamedCount(displayName));
        }
        else
        {
            count.increment();
        }
    }

    private static void mergeNamed(Map<String, NamedCount> target, Map<String, NamedCount> source)
    {
        source.forEach((key, value) ->
        {
            NamedCount existing = target.get(key);
            if (existing == null)
            {
                NamedCount copy = new NamedCount(value.getName());
                copy.add(value.getCount() - 1);
                target.put(key, copy);
            }
            else
            {
                existing.add(value.getCount());
            }
        });
    }

    private static Integer minimum(Integer first, Integer second)
    {
        if (first == null)
        {
            return second;
        }
        return second == null ? first : Math.min(first, second);
    }

    private static Integer maximum(Integer first, Integer second)
    {
        if (first == null)
        {
            return second;
        }
        return second == null ? first : Math.max(first, second);
    }

    private static List<NamedCount> sortedNamed(Map<String, NamedCount> source, boolean repeatsOnly)
    {
        List<NamedCount> result = new ArrayList<>();
        for (NamedCount item : source.values())
        {
            if (!repeatsOnly || item.getCount() > 1)
            {
                result.add(item);
            }
        }
        result.sort(Comparator.comparingInt(NamedCount::getCount).reversed()
            .thenComparing(NamedCount::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(result);
    }

    private static List<NumberCount> sortedNumbers(Map<Integer, Integer> source)
    {
        List<NumberCount> result = new ArrayList<>();
        source.forEach((value, count) -> result.add(new NumberCount(value, count)));
        result.sort(Comparator.comparingInt(NumberCount::getValue));
        return Collections.unmodifiableList(result);
    }

    static final class NumberCount
    {
        private final int value;
        private final int count;

        NumberCount(int value, int count)
        {
            this.value = value;
            this.count = count;
        }

        int getValue()
        {
            return value;
        }

        int getCount()
        {
            return count;
        }
    }

    static final class Snapshot
    {
        private final int totalMessages;
        private final long levelTotal;
        private final long damageTotal;
        private final Integer minimumLevel;
        private final Integer maximumLevel;
        private final Integer minimumDamage;
        private final Integer maximumDamage;
        private final List<NamedCount> monsters;
        private final List<NamedCount> repeatedPlayers;
        private final List<NamedCount> locations;
        private final List<NumberCount> levels;
        private final List<NumberCount> damages;

        Snapshot(int totalMessages, long levelTotal, long damageTotal, Integer minimumLevel, Integer maximumLevel,
                 Integer minimumDamage, Integer maximumDamage, List<NamedCount> monsters,
                 List<NamedCount> repeatedPlayers, List<NamedCount> locations,
                 List<NumberCount> levels, List<NumberCount> damages)
        {
            this.totalMessages = totalMessages;
            this.levelTotal = levelTotal;
            this.damageTotal = damageTotal;
            this.minimumLevel = minimumLevel;
            this.maximumLevel = maximumLevel;
            this.minimumDamage = minimumDamage;
            this.maximumDamage = maximumDamage;
            this.monsters = monsters;
            this.repeatedPlayers = repeatedPlayers;
            this.locations = locations;
            this.levels = levels;
            this.damages = damages;
        }

        int getTotalMessages() { return totalMessages; }
        double getAverageLevel() { return totalMessages == 0 ? 0 : (double) levelTotal / totalMessages; }
        double getAverageDamage() { return totalMessages == 0 ? 0 : (double) damageTotal / totalMessages; }
        double getMedianLevel() { return median(levels, totalMessages); }
        double getMedianDamage() { return median(damages, totalMessages); }
        Integer getMinimumLevel() { return minimumLevel; }
        Integer getMaximumLevel() { return maximumLevel; }
        Integer getMinimumDamage() { return minimumDamage; }
        Integer getMaximumDamage() { return maximumDamage; }
        List<NamedCount> getMonsters() { return monsters; }
        List<NamedCount> getRepeatedPlayers() { return repeatedPlayers; }
        List<NamedCount> getLocations() { return locations; }
        List<NumberCount> getLevels() { return levels; }
        List<NumberCount> getDamages() { return damages; }

        private static double median(List<NumberCount> values, int total)
        {
            if (total == 0)
            {
                return 0;
            }

            int lowerPosition = (total + 1) / 2;
            int upperPosition = (total + 2) / 2;
            Integer lowerValue = null;
            int seen = 0;
            for (NumberCount value : values)
            {
                seen += value.getCount();
                if (lowerValue == null && seen >= lowerPosition)
                {
                    lowerValue = value.getValue();
                }
                if (seen >= upperPosition)
                {
                    return (lowerValue + value.getValue()) / 2.0;
                }
            }
            throw new IllegalStateException("Frequency counts do not match the message total");
        }
    }
}

package com.deathmessagetracker;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import net.runelite.client.util.Filepath;

final class TrackerStore
{
    private final Gson gson;
    private final Filepath dataFile;

    TrackerStore(Gson gson, Filepath dataFile)
    {
        this.gson = gson;
        this.dataFile = dataFile;
    }

    TrackerState load() throws IOException
    {
        if (!dataFile.exists())
        {
            return new TrackerState();
        }

        try (Reader reader = dataFile.openBufferedReader())
        {
            TrackerState state = gson.fromJson(reader, TrackerState.class);
            if (state == null)
            {
                return new TrackerState();
            }
            state.normalizeAfterLoad();
            return state;
        }
    }

    void save(TrackerState state) throws IOException
    {
        Filepath parent = dataFile.getParent();
        parent.createDirectories();
        Filepath temporaryFile = parent.joinSegment(dataFile.getFileName() + ".tmp");
        try (Writer writer = temporaryFile.openBufferedWriter(
            StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
        {
            writer.write(state.toJson(gson));
        }

        try
        {
            temporaryFile.moveTo(dataFile, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        }
        catch (AtomicMoveNotSupportedException ignored)
        {
            temporaryFile.moveTo(dataFile, StandardCopyOption.REPLACE_EXISTING);
        }
    }
}

package com.deathmessagetracker;

import java.util.Optional;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DeathMessageParserTest
{
    @Test
    public void parsesMessageWithSpacesInNames()
    {
        Optional<DeathMessage> result = DeathMessageParser.parse(
            "Moss giant killed Edge Cases(106) with a 5 damage hit in Kandarin.");

        assertTrue(result.isPresent());
        DeathMessage message = result.get();
        assertEquals("Moss giant", message.getMonster());
        assertEquals("Edge Cases", message.getUsername());
        assertEquals(106, message.getLevel());
        assertEquals(5, message.getDamage());
        assertEquals("Kandarin", message.getLocation());
    }

    @Test
    public void removesRuneLiteMarkupAndNormalizesWhitespace()
    {
        Optional<DeathMessage> result = DeathMessageParser.parse(
            "<col=ff7000>@mes_hl_ora@Dark wizard  killed  Uncle Mike 9(180) with a 1 damage hit in Misthalin.</col>");

        assertTrue(result.isPresent());
        assertEquals("Dark wizard", result.get().getMonster());
        assertEquals("Uncle Mike 9", result.get().getUsername());
    }

    @Test
    public void ignoresUnrelatedChat()
    {
        assertFalse(DeathMessageParser.parse("You cast out your net... (15)").isPresent());
        assertFalse(DeathMessageParser.parse("You catch some raw shrimps. (54)").isPresent());
    }
}

