package com.deathmessagetracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TrackerStateTest
{
    @Test
    public void aggregatesWithoutRetainingMessages()
    {
        TrackerState state = new TrackerState();
        state.add(new DeathMessage("Wolf", "Player One", 100, 4, "Kandarin"));
        state.add(new DeathMessage("wolf", "player one", 120, 8, "kandarin"));

        TrackerState.Snapshot snapshot = state.snapshot();
        assertEquals(2, snapshot.getTotalMessages());
        assertEquals(1, snapshot.getMonsters().size());
        assertEquals(2, snapshot.getMonsters().get(0).getCount());
        assertEquals(1, snapshot.getRepeatedPlayers().size());
        assertEquals(110.0, snapshot.getAverageLevel(), 0.001);
        assertEquals(110.0, snapshot.getMedianLevel(), 0.001);
        assertEquals(6.0, snapshot.getAverageDamage(), 0.001);
        assertEquals(6.0, snapshot.getMedianDamage(), 0.001);
        assertEquals(Integer.valueOf(100), snapshot.getMinimumLevel());
        assertEquals(Integer.valueOf(120), snapshot.getMaximumLevel());
        assertEquals(Integer.valueOf(4), snapshot.getMinimumDamage());
        assertEquals(Integer.valueOf(8), snapshot.getMaximumDamage());
    }

    @Test
    public void mergesLoadedAggregatesWithMessagesReceivedDuringStartup()
    {
        TrackerState current = new TrackerState();
        current.add(new DeathMessage("Wolf", "Player One", 100, 4, "Kandarin"));
        TrackerState loaded = new TrackerState();
        loaded.add(new DeathMessage("wolf", "player one", 120, 8, "kandarin"));

        current.mergeFrom(loaded);

        TrackerState.Snapshot snapshot = current.snapshot();
        assertEquals(2, snapshot.getTotalMessages());
        assertEquals(2, snapshot.getMonsters().get(0).getCount());
        assertEquals(1, snapshot.getRepeatedPlayers().size());
        assertEquals(110.0, snapshot.getMedianLevel(), 0.001);
    }
}
